const BOX = `${VIEW.x} ${VIEW.y} ${VIEW.w} ${VIEW.h}`;

/** Static wordmark. Takes its colour from `currentColor`. */
export function Wordmark({ height = 20, title = 'Groundwork' }: { height?: number; title?: string }) {
  return (
    <svg
      className="wordmark"
      viewBox={BOX}
      height={height}
      width={height * (VIEW.w / VIEW.h)}
      role="img"
      aria-label={title}
      fill="currentColor"
    >
      <path d={PATH} />
    </svg>
  );
}

/**
 * The wordmark as the progress indicator.
 *
 * The letterforms fill left to right rather than a bar filling beside them, so
 * the mark and the progress are one object. Two draws of the same outline: the
 * lower one at rest, the upper one clipped to a rect whose width tracks
 * progress, which means the fill follows the strokes exactly instead of
 * sweeping a block across them.
 *
 * The rect is animated in USER UNITS via a CSS transition on `width`; the
 * clip lives in the same coordinate space as the glyphs, so it stays aligned at
 * any rendered size.
 */
export function WordmarkProgress({
  progress,
  height = 46,
}: {
  /** 0 to 1. */
  progress: number;
  height?: number;
}) {
  const id = useId().replace(/:/g, '');
  const p = Math.max(0, Math.min(1, progress));

  return (
    <svg
      className="wordmark-progress"
      viewBox={BOX}
      height={height}
      width={height * (VIEW.w / VIEW.h)}
      role="progressbar"
      aria-valuenow={Math.round(p * 100)}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-label="Loading"
    >
      <defs>
        <clipPath id={`wm-${id}`}>
          <rect
            className="wm-clip"
            x={VIEW.x}
            y={VIEW.y}
            height={VIEW.h}
            width={VIEW.w * p}
          />
        </clipPath>
      </defs>
      <path className="wm-rest" d={PATH} />
      <path className="wm-fill" d={PATH} clipPath={`url(#wm-${id})`} />
    </svg>
  );
}
